 if(data.type==='start'){if(sink)throw Error('Recording is already active.');if(!Number.isSafeInteger(data.width)||!Number.isSafeInteger(data.height)||data.width<2||data.height<2||data.width>2048||data.height>2048||data.width%2||data.height%2)throw Error('Invalid recording dimensions.');plan={width:data.width,height:data.height,rate:{n:30,d:1},frames:18000,quality:32};importScripts('./vp9-stream-encoder.js');sink=await createForgeVp9Sink(plan);self.postMessage({type:'ready'});}
